insert into public.foods (
  name, description, food_type, measurement_state,
  calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fiber_per_100g,
  source, source_id, is_global
)
select
  s.name, s.description, s.food_type, s.measurement_state,
  s.calories_per_100g, s.protein_per_100g, s.carbs_per_100g, s.fat_per_100g, s.fiber_per_100g,
  s.source, s.source_id, s.is_global
from seed s
where not exists (
  select 1
  from public.foods f
  where f.is_global = true
    and lower(f.name) = lower(s.name)
    and f.measurement_state = s.measurement_state
);

-- Refresh the catalog search index after the bulk insert.
analyze public.foods;
